(function (g) {
  'use strict';
  var raw = g.__extInvoke;
  g.__extInvoke = function (handle, args) {
    var reply = function (ok, v) {
      var msg = ok
        ? { invoke: handle, ok: true, value: v === undefined ? null : v }
        : { invoke: handle, ok: false, error: String(v && v.message ? v.message : v) };
