import 'package:flutter_test/flutter_test.dart';

void main() {
  test('JsAppEngine.dispose is safe without a widget binding', () async {
    final engine = JsAppEngine(
      app: JsAppInfo.fromManifest(
        const {'id': 'demo', 'name': 'Demo'},
        bundled: false,
        fallbackId: 'demo',
